    "// OCaml Command Injection Detection Rule // Detects shell command injection via OCaml process execution functions // Matches patterns found in gleam.ml: grammar_path() and extract()  rule \"OCamlCommandInjection\" severity=\"Critical\" {     sinks {         sink \"Unix.open_process_full\" arg=0 {             sanitizer \"Filename.quote\"             sanitizer \"Core.Filename.quote\"             sanitizer \"Filename.dirname\"             sanitizer \"Filename.basename\"             fix \"Use Unix.create_process with array arguments instead of shell string\"         }         sink \"Unix.open_process_in\" arg=0 {             sanitizer \"Filename.quote\"             sanitizer \"Core.Filename.quote\"             fix \"Use Unix.create_process or validate command string thoroughly\"         }         sink \"Unix.open_process_out\" arg=0 {             sanitizer \"Filename.quote\"             sanitizer \"Core.Filename.quote\"             fix \"Use Unix.create_process to avoid shell interpretation\"         }         sink \"Sys.command\" arg=0 {             sanitizer \"Filename.quote\"             sanitizer \"Core.Filename.quote\"             fix \"Sys.command invokes /bin/sh - use Unix.create_process for safe argument separation\"         }         sink \"Stdlib.Sys.command\" arg=0 {             sanitizer \"Filename.quote\"             sanitizer \"Core.Filename.quote\"             fix \"Use Unix.create_process with separate arguments\"         }         sink \"Core.Shell.run\" arg=0 {             fix \"Validate command arguments before passing to Core.Shell.run\"         }         sink \"Core.Process.exec\" arg=0 {             fix \"Use Core.Process.run with explicit argument list\"         }     }     sources {         source \"Sys.getenv\"         source \"Stdlib.Sys.getenv\"         source \"Unix.environment\"         source \"Core.Env.get\"         source \"ARGV\"         source \"params\"         source \"user_input\"         source \"request\"         source \"file_path\"         source \"path\"         source \"grammar_path\"     }     message \"Potential command injection in OCaml: {sink} receives unsanitized input. OCaml process execution functions invoke /bin/sh, allowing arbitrary command execution if paths or arguments contain shell metacharacters (single quotes, semicolons, pipes, etc.).\\n\\nDetected in: gleam.ml grammar_path() and extract() functions.\\nFix: Use Unix.create_process with array arguments to avoid shell interpretation.\" }  rule \"OCamlShellInterpolation\" severity=\"High\" {     sinks {         sink \"Printf.sprintf\" {             pattern \"Unix.open_process\"             pattern \"Sys.command\"             fix \"Avoid building shell commands with sprintf - use create_process with argument array\"         }     }     sources {         source \"Sys.getenv\"         source \"Stdlib.Sys.getenv\"         source \"file_path\"         source \"grammar_path\"     }     message \"Shell command built via Printf.sprintf with interpolated paths: {sinks}. If any interpolated value contains single quotes or shell metacharacters, command injection is possible.\\n\\nExample vulnerable pattern:\\n  let cmd = Printf.sprintf \\\"find '%s'\\\" user_path in\\n  Unix.open_process_in cmd\\n\\nSafe pattern:\\n  Unix.create_process \\\"find\\\" [| \\\"find\\\"; user_path |] ...\" } ";
    "// OCaml Error Context Detection Rule // Detects error handling that loses valuable debugging and security audit information // Matches patterns found in parallel.ml:80 - hardcoded \"unknown file\" strings  rule \"MissingErrorContext\" severity=\"Medium\" {     sinks {         sink \"Failed\" arg=0 {             sanitizer \"file\"             sanitizer \"path\"             sanitizer \"src.path\"             sanitizer \"src\"             fix \"Include actual file path or identifier in error context\"         }     }     patterns {         pattern \"HardcodedUnknownFile\" {             match \"\\\"unknown file\\\"\"             message \"Hardcoded error context 'unknown file' detected in error handler. This loses valuable debugging information and makes security audit trail incomplete (CWE-755: Improper Check for Unusual or Exceptional Conditions).\\n\\nFound in: parallel.ml:80\\n  file = \\\"unknown file\\\";\\n\\nThis pattern indicates an error handler that cannot provide meaningful context about which file failed, making incident response and debugging difficult.\\n\\nFix: Pass the actual file path to the error context:\\n  file = source_file.path;  (* Include actual file for debugging *)\"             severity \"Medium\"         }         pattern \"HardcodedErrorMessage\" {             match \"\\\"unknown error\\\"\"             message \"Hardcoded error context 'unknown error' detected. Include actual error information.\"             severity \"Low\"         }         pattern \"OpaqueError\" {             match \"\\\"failed\\\"\"             message \"Generic error message 'failed' provides no debugging context. Include specific error details.\"             severity \"Low\"         }     }     message \"Error handling loses context. Using hardcoded strings like 'unknown file' in error handlers prevents effective debugging and security audit trail analysis.\" }  rule \"SilentErrorSwallow\" severity=\"Low\" {     languages { include \"ocaml\" }     conditions { skip_taint_check }     sinks {         sink \"try\" match=\"exact\" {             pattern \"_ -> ()\"             pattern \"_ -> ()\"             pattern \"with _ -> ()\"             pattern \"with exn -> ()\"             fix \"Log or report errors instead of silently swallowing them\"         }     }     message \"Error silently swallowed with empty handler. Errors should be logged or propagated for proper monitoring and incident response.\" } ";
    "// OCaml Race Condition Detection Rule // Detects PID-based temp file patterns vulnerable to symlink attacks (CWE-377, CWE-378) // Matches patterns found in orchestrator.ml:46  rule \"RaceConditionTempFile\" severity=\"High\" {     sinks {         sink \"Printf.sprintf\" {             pattern \"getpid\"             pattern \"Unix.getpid\"             fix \"Use Filename.open_temp_file or cryptographic random suffix instead of PID\"         }         sink \"In_channel.read_all\" arg=0 {             sanitizer \"Filename.realpath\"             sanitizer \"Secure_random.string\"             fix \"Validate temp file path is within expected directory before reading\"         }         sink \"Out_channel.write\" arg=0 {             sanitizer \"Secure_random.string\"             fix \"Use Filename.open_temp_file for atomic temp file creation\"         }         sink \"Core.Out_channel.write\" arg=0 {             sanitizer \"Secure_random.string\"             fix \"Use Core.In_channel.with_file or Filename.open_temp_file\"         }         sink \"Core.In_channel.read_all\" arg=0 {             sanitizer \"Secure_random.string\"             fix \"Validate temp file path before reading\"         }         sink \"Stdlib.Buffer.add_channel\" arg=1 {             fix \"Use secure temp file with random name, not PID-based\"         }     }     message \"PID-based temp file path detected. Using Unix.getpid() creates predictable paths vulnerable to symlink attacks (CWE-377: Creation of Temporary File With Insecure Permissions, CWE-378: Creation of Temporary File Insecurely).\\n\\nVulnerable pattern (orchestrator.ml:46):\\n  let tmp_file = Printf.sprintf \\\"/tmp/catseye-extract-%d.out\\\" (Unix.getpid ()) in\\n  let content = Core.In_channel.read_all tmp_file\\n\\nAn attacker can:\\n1. Monitor for new processes\\n2. Create a symlink at /tmp/catseye-extract-{pid}.out before the process accesses it\\n3. Gain read/write access to arbitrary files\\n\\nSafe pattern:\\n  let (tmp_file, oc) = Filename.open_temp_file ~perms:0o600 \\\"catseye-extract-\\\" \\\".out\\\" in\\n  (* Use tmp_file safely - file is created atomically with secure permissions *)\" }  rule \"InsecureTempFilePermissions\" severity=\"Medium\" {     sinks {         sink \"open_out\" arg=0 {             sanitizer \"perms:0o600\"             fix \"Use Filename.open_temp_file with restrictive permissions (0o600)\"         }         sink \"Stdlib.open_out\" arg=0 {             sanitizer \"perms:0o600\"             fix \"Specify restrictive permissions to prevent unauthorized access\"         }     }     message \"Temp file created without secure permissions. Files in /tmp are world-readable by default. Use Filename.open_temp_file with perms:0o600 or create files in a secure directory.\" } ";
    "// OCaml Unsafe Operations Detection Rule // Detects unsafe type system bypasses and deserialization vulnerabilities // Obj.magic, Marshal.from_string can lead to type confusion and RCE (CWE-502)  rule \"OCamlUnsafeOperations\" severity=\"High\" {     sinks {         sink \"Obj.magic\" arg=0 {             fix \"Avoid Obj.magic - use typed conversions or sum types for type safety\"         }         sink \"Obj.repr\" arg=0 {             fix \"Obj.repr bypasses type system - use typed data structures instead\"         }         sink \"Obj.set\" arg=0 {             fix \"Obj.set modifies internal object structure - avoid runtime manipulation\"         }         sink \"Obj.obj\" arg=0 {             fix \"Obj.obj creates arbitrary values - use type-safe constructors\"         }         sink \"Marshal.from_string\" arg=0 {             sanitizer \"Digest.SHA256.hexdigest\"             sanitizer \"hmac\"             fix \"Marshal.from_string deserializes arbitrary OCaml values - use JSON or type-safe serialization (Yojson, sexplib) to prevent RCE\"         }         sink \"Marshal.from_channel\" arg=0 {             sanitizer \"Digest.SHA256.hexdigest\"             fix \"Marshal deserialization is unsafe with untrusted data\"         }         sink \"Marshal.input_value\" arg=0 {             fix \"Marshal.input_value can execute arbitrary code - use safe deserialization\"         }         sink \"deriving\" arg=0 {             pattern \"unsafe_yojson\"             fix \"unsafe_yojson bypasses validation - use safe_yojson or explicit validation\"         }     }     sources {         source \"In_channel.read_all\"         source \"Stdlib.read_line\"         source \"request\"         source \"body\"         source \"params\"         source \"user_input\"     }     message \"Unsafe OCaml operation {sink} detected. These operations bypass the type system and can lead to:\\n\\n- Type confusion attacks (CWE-843)\\n- Arbitrary memory access (CWE-125)\\n- Remote code execution via malicious Marshal data (CWE-502)\\n\\nVulnerable patterns:\\n  let unsafe_cast x = (Obj.magic x : int)  (* Type confusion *)\\n  let data = Marshal.from_string (read_file path) 0  (* RCE if file is attacker-controlled *)\\n\\nSafe patterns:\\n  (* Use typed conversions or sum types *)\\n  let safe_unpack json = Yojson.Safe.from_string json  (* Type-safe *)\\n  let typed_convert (x : A.t) : B.t = match x with ...  (* Explicit *)\\n\\nFor Marshal: Only deserialize data from trusted sources, or use HMAC verification:\\n  let verified_data = if check_hmac (Marshal.from_string data 0) then ...\" }  rule \"OCamlMarshalDeserialization\" severity=\"Critical\" {     sinks {         sink \"Marshal.from_string\" arg=0 {             fix \"Never deserialize untrusted data with Marshal - use JSON with AoC validation\"         }         sink \"Marshal.from_channel\" arg=0 {             fix \"Use type-safe serialization for external data\"         }         sink \"Marshal.input_value\" arg=0 {             fix \"input_value is inherently unsafe with network input\"         }     }     sources {         source \"In_channel.read_all\"         source \"request\"         source \"body\"         source \"params\"         source \"user_input\"         source \"file_path\"         source \"Sys.getenv\"     }     message \"CRITICAL: Marshal deserialization with potentially untrusted input. Marshal is NOT a safe serialization format for external data. An attacker can craft malicious OCaml data that executes arbitrary code upon deserialization.\\n\\nCVE-2013-4162 and similar vulnerabilities exist in all OCaml Marshal operations.\\n\\nRequired fixes:\\n1. Never use Marshal with user-controlled input\\n2. Replace with JSON + explicit type parsing (Yojson, Atdgen)\\n3. If Marshal is required, add HMAC verification before deserializing\" } ";
    "rule \"OpenRedirect\" severity=\"Medium\" {     languages {         exclude \"crystal\"         exclude \"svelte\"     }     sinks {         sink \"redirect_to\" arg=0 {             fix \"redirect_to(validate_url({arg0}))\"         }         sink \"response.redirect\" arg=0 {             fix \"response.redirect(validate_url({arg0}))\"         }         sink \"send_redirect\" arg=0 {             fix \"Validate URL is relative or allowlisted: send_redirect(validate_url({arg0}))\"         }     }     sources {         source \"params\" field=\"url\"         source \"url\"         source \"redirect_url\"         source \"return_to\"         source \"next\"     }     message \"Potential open redirect via {sink} with user-controlled URL: {tainted_vars}.\" } ";
    "rule \"PathTraversal\" severity=\"High\" {     languages {         exclude \"crystal\"         exclude \"svelte\"     }     sinks {         sink \"File.read\" arg=0 {             sanitizer \"Path.basename\"             sanitizer \"Path.dirname\"             sanitizer \"Path.posix\"             sanitizer \"Digest::MD5.hexdigest\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             sanitizer \"hexdigest\"             sanitizer \"Base64.encode\"             sanitizer \"File.expand_path\"             sanitizer \"validate_\"             fix \"File.read(File.expand_path({arg0}))\"         }         sink \"File.write\" arg=0 {             sanitizer \"Path.basename\"             sanitizer \"Digest::MD5.hexdigest\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             sanitizer \"hexdigest\"             sanitizer \"Base64.encode\"             sanitizer \"File.expand_path\"             sanitizer \"validate_\"             fix \"File.write(File.expand_path({arg0}))\"         }         sink \"File.delete\" arg=0 {             sanitizer \"Digest::MD5.hexdigest\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             sanitizer \"hexdigest\"             sanitizer \"File.expand_path\"             sanitizer \"validate_\"             fix \"File.delete(File.expand_path({arg0}))\"         }         sink \"File.open\" arg=0 {             sanitizer \"Digest::MD5.hexdigest\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             sanitizer \"hexdigest\"             sanitizer \"File.expand_path\"             sanitizer \"validate_\"             fix \"File.open(File.expand_path({arg0}))\"         }         sink \"Dir.glob\" arg=0 {             sanitizer \"validate_\"             fix \"Validate path components before globbing: Dir.glob(validate_path({arg0}))\"         }         sink \"Dir.entries\" arg=0 {             sanitizer \"validate_\"             fix \"Validate path before listing: Dir.entries(validate_path({arg0}))\"         }         sink \"simplifile.read\" arg=0 {             sanitizer \"validate_\"             fix \"Validate path before reading\"         }         sink \"simplifile.write\" arg=0 {             sanitizer \"validate_\"             fix \"Validate path before writing\"         }         sink \"simplifile.delete\" arg=0 {             sanitizer \"validate_\"             fix \"Validate path before deleting\"         }     }     sources {         source \"params\" field=\"path\"         source \"path\"         source \"url\"         source \"filename\"         source \"filepath\"         source \"user_path\"     }     message \"Potential path traversal via {sink} with variable argument(s): {tainted_vars}. Validate and sanitize path components.\" }  rule \"PathTraversal\" severity=\"Medium\" {     languages {         exclude \"crystal\"         exclude \"svelte\"     }     sinks {         sink \"File.join\" {             sanitizer \"Digest::MD5.hexdigest\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             sanitizer \"hexdigest\"             sanitizer \"Base64.encode\"             sanitizer \"validate_\"             fix \"Validate path components before joining\"         }         sink \"Path.join\" {             sanitizer \"Digest::MD5.hexdigest\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             sanitizer \"hexdigest\"             sanitizer \"Base64.encode\"             sanitizer \"validate_\"             fix \"Validate path components before joining\"         }     }     sources {         source \"params\" field=\"path\"         source \"path\"         source \"url\"         source \"filename\"         source \"filepath\"         source \"user_path\"     }     message \"Potential path traversal via {sink} (path join) with variable argument(s): {tainted_vars}. Validate path components.\" } ";
    "rule \"ReDoS\" severity=\"Medium\" {     sinks {         sink \"Regex.new\" {             fix \"Use a non-backtracking regex engine or simplify nested quantifiers\"         }         sink \"Regex.compile\" {             fix \"Use a non-backtracking regex engine or simplify nested quantifiers\"         }         sink \"re.compile\" {             fix \"re.compile(regex, timeout=1) or simplify nested quantifiers\"         }         sink \"regexp.compile\" {             fix \"Use a non-backtracking regex engine or simplify nested quantifiers\"         }     }     conditions {         check_args_contain \"+)+\"         check_args_contain \"+)*\"         check_args_contain \"*)+\"         check_args_contain \"*)*\"         check_args_contain \"?)\"     }     message \"Potential ReDoS: regex with nested quantifiers or overlapping groups. Catastrophic backtracking risk.\" } ";
    "// Rust-specific security rules // Covers SSRF, command injection, path traversal, unsafe code // All rules scoped to Rust only — does not apply to other languages  rule \"RustUnsafeBlock\" severity=\"High\" {     languages { include \"rust\" }     // Detect unsafe blocks that may need auditing     sinks {         sink \"unsafe\" match=\"exact\" {             fix \"Review unsafe block for memory safety issues. Document invariants.\"         }     }     message \"Unsafe block without documented safety invariants\" }  rule \"RustCommandInjection\" severity=\"High\" {     languages { include \"rust\" }     // Command injection via std::process::Command     sinks {         sink \"Command::new\" arg=0 {             sanitizer \"String::from\"             sanitizer \".to_string()\"             sanitizer \"std::path::Path::new\"         }         sink \"Command::arg\" arg=0 {             sanitizer \"String::from\"             sanitizer \".to_string()\"         }         sink \"Command::args\" arg=0 {             sanitizer \".to_string()\"         }     }     sources {         source \"std::env::var\"         source \"std::env::args\"     }     message \"Potential command injection via Command::new() with user input\" }  rule \"RustPathTraversal\" severity=\"Medium\" {     languages { include \"rust\" }     // Path traversal via fs operations     sinks {         sink \"fs::read\" arg=0         sink \"fs::read_to_string\" arg=0         sink \"fs::write\" arg=0         sink \"fs::create_dir\" arg=0         sink \"fs::remove_file\" arg=0         sink \"std::fs::File::open\" arg=0 {             sanitizer \"std::path::Path::new\"             sanitizer \"std::path::PathBuf::from\"         }     }     sources {         source \"std::env::var\"         source \"request\"         source \"params\"     }     message \"Potential path traversal via filesystem operation\" }  rule \"RustSSRF\" severity=\"High\" {     languages { include \"rust\" }     // SSRF via HTTP clients     sinks {         sink \"reqwest::blocking::get\" arg=0 {             sanitizer \"Url::parse\"             sanitizer \"reqwest::Url\"         }         sink \"reqwest::get\" arg=0 {             sanitizer \"Url::parse\"         }         sink \"reqwest::post\" arg=0 {             sanitizer \"Url::parse\"         }         sink \"ureq::get\" arg=0 {             sanitizer \"Url::parse\"         }         sink \"ureq::post\" arg=0 {             sanitizer \"Url::parse\"         }         sink \"attohttpc::get\" arg=0 {             sanitizer \"Url::parse\"         }     }     sources {         source \"std::env::var\"         source \"request\"         source \"params\"         source \"user_url\"     }     message \"Potential SSRF via HTTP client with user-controlled URL\" }  rule \"RustIntegerOverflow\" severity=\"Medium\" {     languages { include \"rust\" }     // Integer overflow in release mode (wraps silently)     sinks {         sink \"+\" match=\"exact\" {             sanitizer \"checked_add\"             sanitizer \"saturating_add\"             sanitizer \"wrapping_add\"         }         sink \"-\" match=\"exact\" {             sanitizer \"checked_sub\"             sanitizer \"saturating_sub\"             sanitizer \"wrapping_sub\"         }         sink \"*\" match=\"exact\" {             sanitizer \"checked_mul\"             sanitizer \"saturating_mul\"             sanitizer \"wrapping_mul\"         }     }     message \"Integer operation may overflow silently in release mode\" }  rule \"RustPanicInLibrary\" severity=\"Medium\" {     languages { include \"rust\" }     // panic!, unwrap(), expect() in library code     sinks {         sink \"panic\" match=\"exact\" {             fix \"Return Result<T, E> instead of panicking\"         }         sink \"unwrap\" match=\"exact\" {             fix \"Use ? operator or provide default value with unwrap_or()\"         }         sink \"expect\" match=\"exact\" {             fix \"Return Result or use unwrap_or() with proper error message\"         }     }     message \"Panic-inducing code in library code\" }  rule \"RustHardcodedCredentials\" severity=\"High\" {     languages { include \"rust\" }     // Hardcoded passwords, API keys, tokens     sinks {         sink \"password\" match=\"exact\" {             fix \"Use environment variable or secrets manager\"         }         sink \"api_key\" match=\"exact\" {             fix \"Use environment variable or secrets manager\"         }         sink \"secret\" match=\"exact\" {             fix \"Use environment variable or secrets manager\"         }         sink \"token\" match=\"exact\" {             fix \"Use environment variable or secrets manager\"         }     }     message \"Potential hardcoded credential\" } ";
    "rule \"ScentLeakage\" severity=\"Critical\" {     sinks {         // Crystal log sinks         sink \"Logger.info\" {             // URLs validated through SSRF checks are safe to log (diagnostic info)             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Logger.warn\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Logger.error\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Logger.debug\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Logger.notice\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Log.info\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Log.warn\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Log.error\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Log.debug\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         sink \"Log.notice\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid logging sensitive data — redact or mask before logging\"         }         // Crystal output sinks         sink \"puts\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             sanitizer \"allowlisted_url?\"             sanitizer \"Digest::SHA256.hexdigest\"             sanitizer \"OpenSSL::Digest\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"pp!\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"print\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"STDOUT.puts\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"STDOUT.write\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"STDERR.puts\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"STDERR.write\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid printing sensitive data — redact or mask before output\"         }         sink \"Log.write\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid logging sensitive data — redact or mask\"         }         sink \"IO.write\" {             sanitizer \"check_ssrf\"             sanitizer \"validate_url\"             fix \"Avoid writing sensitive data to unsecured output — redact or mask\"         }     }     sources {         source \"password\"         source \"token\"         source \"secret\"         source \"api_key\"         source \"credential\"         source \"private_key\"         source \"access_token\"         source \"refresh_token\"         source \"auth_key\"     }     message \"Scent Leakage: sensitive data may reach {sink} via scented variable(s): {tainted_vars}.\" }";
    "rule \"SQLInjection\" severity=\"Critical\" {     sinks {         sink \"db.exec\" arg=0 {             fix \"Use parameterized queries: db.exec(\\\"SELECT ... WHERE id = $1\\\", [{arg0}])\"         }         sink \"db.query\" arg=0 {             fix \"Use parameterized queries: db.query(\\\"SELECT ... WHERE id = $1\\\", [{arg0}])\"         }         sink \"db.scalar\" arg=0 {             fix \"Use parameterized queries: db.scalar(\\\"SELECT ... WHERE id = $1\\\", [{arg0}])\"         }         sink \"db.query_one\" arg=0 {             fix \"Use parameterized queries: db.query_one(\\\"SELECT ... WHERE id = $1\\\", [{arg0}])\"         }         sink \"db.query_all\" arg=0 {             fix \"Use parameterized queries: db.query_all(\\\"SELECT ... WHERE id = $1\\\", [{arg0}])\"         }         sink \"db.execute\" arg=0 {             fix \"Use parameterized queries: db.execute(\\\"INSERT ... VALUES ($1)\\\", [{arg0}])\"         }         sink \"database.exec\" arg=0 {             fix \"Use parameterized queries instead of string interpolation\"         }         sink \"database.query\" arg=0 {             fix \"Use parameterized queries instead of string interpolation\"         }     }     sources {         source \"params\"         source \"query\"         source \"user_input\"         source \"request\"     }     message \"Potential SQL injection via {sink} with tainted argument(s): {tainted_vars}.\" } ";
